"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useFormik } from "formik";
import axiosInstance from "@/utils/axiosInstance";
import Select from "react-select";
import { useCategories } from "@/hooks/useCategories";
import { Product, Category, ProductStatus } from "@/types/product";
import { FiTrash, FiUploadCloud } from "react-icons/fi";
import { toast, ToastContainer } from "react-toastify";
import ProductFormSkeleton from "./productFormSkeleton";
import { validationSchema } from "@/components/product/draft/validationSchemas"
import { formatNumber, parseNumber } from "@/utils/FormatNumber"
import { DraftForm } from "@/components/product/draft/DraftForm"

const ProductDraftForm = () => {
  const params = useParams();
  const productId = params?.productId as string;
  const router = useRouter();
  const { data: categoryData, isLoading } = useCategories(1, 100, "");

  const [productData, setProductData] = useState<Product | null>(null);
  const [isSubmitting, setSubmitting] = useState(false);
  const [localProductPictures, setLocalProductPictures] = useState<(string | null)[]>([null, null, null]);
  const [showCancelModal, setShowCancelModal] = useState(false);

  const fetchProducts = async () => {
    try {
      const response = await axiosInstance.get<Product>(`/products/${productId}`);
      const product = response.data;

      if (!product || Object.values(product).every((value) => value === null)) {
        router.push("/404");
        return;
      }

      setProductData(product);

      if (product.status !== ProductStatus.DRAFT) {
        router.push("/403");
        return;
      }

    } catch (error) {
      router.push("/404");
    }
  };

  useEffect(() => {
    if (productId && !productData) {
      console.log("Fetching product data for ID:", productId);
      fetchProducts();
    }
  }, [productId]);

  const formik = useFormik({
    initialValues: {
      productName: productData?.productName || "",
      detail: productData?.detail || "",
      price: productData?.price || "",
      weight: productData?.weight || "",
      productCategory: productData?.categoryId ? String(productData.categoryId) : "",
      productPictures: productData?.productPictures?.map((pic) => pic.productPictureUrl) || [null, null, null],
    },
    enableReinitialize: true,
    validationSchema,
    onSubmit: async (values, { setSubmitting, setFieldTouched }) => {
      setSubmitting(true);
    
      const errors = await formik.validateForm();
      if (Object.keys(errors).length > 0) {
        Object.keys(errors).forEach((field) => {
          setFieldTouched(field, true);
        });
        setSubmitting(false);
        return;
      }
    
      try {
        await axiosInstance.patch(`/products/${productId}/create`, values);
        router.push("/dashboard/admin/products");
        localStorage.setItem("toastMessage", "Product created successfully!");
      } catch (error: any) {
        console.error("Product creation failed:", error.response?.data || error.message);
    
        if (error.response?.status === 409) {
          formik.setFieldError("productName", "Product name already exists. Please choose a different name.");
        }
      } finally {
        setSubmitting(false);
      }
    }
  });

  useEffect(() => {
    if (productData) {
      const initialPictures: (string | null)[] = [null, null, null];

      if (productData.productPictures && Array.isArray(productData.productPictures)) {
        productData.productPictures.forEach((pic) => {
          if (pic.position >= 1 && pic.position <= 3) {
            initialPictures[pic.position - 1] = pic.productPictureUrl;
          }
        });
      }

      setLocalProductPictures(initialPictures); // Set local state for pictures
      formik.setFieldValue("productPictures", initialPictures);
    }
  }, [productData]);

  const handleUploadPicture = async (position: number) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "image/*";
    input.click();

    input.onchange = async (event) => {
      const file = (event.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        setSubmitting(true);
        const formData = new FormData();
        formData.append("file", file);

        await axiosInstance.post(`/pictures/${productId}/${position}/upload`, formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        });

        const newPictures = [...localProductPictures];
        newPictures[position - 1] = URL.createObjectURL(file);
        setLocalProductPictures(newPictures);
        formik.setFieldValue("productPictures", newPictures);
        formik.setTouched({ ...formik.touched, productPictures: true });

        toast.success("Picture uploaded successfully!");
      } catch (error) {
        toast.error("Failed to upload picture");
      } finally {
        setSubmitting(false);
      }
    };
  };

  const handleDeletePicture = async (position: number) => {
    try {
      setSubmitting(true);

      await axiosInstance.delete(`/pictures/${productId}/${position}/delete`);

      const newPictures = [...localProductPictures];
      newPictures[position - 1] = null;
      setLocalProductPictures(newPictures);
      formik.setFieldValue("productPictures", newPictures);
      formik.setTouched({ ...formik.touched, productPictures: true });

      toast.success("Picture deleted successfully!");
    } catch (error) {
      toast.error("Error deleting picture");
    } finally {
      setSubmitting(false);
    }
  };

  const handleSaveDraft = async () => {
    try {
      const draftValues = { ...formik.values, categoryId: formik.values.productCategory };
      const { productCategory, ...finalValues } = draftValues;
      await axiosInstance.patch(`/products/${productId}/draft`, finalValues);
      router.push("/dashboard/admin/products");
      localStorage.setItem('toastMessage', 'Draft saved successfully!');
    } catch (error) {
      localStorage.setItem('toastMessage', 'Failed to save draft');

    }
  };

  const handleCancel = () => {
    setShowCancelModal(true);
  };

  const handleDeleteProduct = async () => {
    try {
      await axiosInstance.delete(`/products/${productId}/delete`);
      router.push("/dashboard/admin/products");
      localStorage.setItem('toastMessage', 'Draft deleted successfully!');
    } catch (error) {
      localStorage.setItem('toastMessage', 'Failed to delete the draft');
    }
  };

  useEffect(() => {
    formik.validateForm();
  }, []);

  useEffect(() => {
    formik.setTouched({
      productName: true,
      detail: true,
      price: true,
      weight: true,
      productCategory: true,
      productPictures: true,
    });
  }, []);

  useEffect(() => {
    console.log("Formik Values:", formik.values);
    console.log("Formik Errors:", formik.errors);
  }, [formik.values, formik.errors]);
  
  

  return (
    <div className="p-8 bg-white shadow-lg rounded-xl max-w-3xl mx-auto">
      <ToastContainer />
      {isLoading || !productData ? (
        <ProductFormSkeleton />
      ) : (
        <>
      <h2 className="text-3xl font-bold mb-6 text-center text-gray-800">📝 Create Product Form</h2>

      <form onSubmit={formik.handleSubmit} className="space-y-6">
        {/* Product Name */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Product Name</label>
          <input
            type="text"
            className="w-full p-3 border rounded-lg text-gray-700 focus:ring-2 focus:ring-blue-400 focus:outline-none"
            {...formik.getFieldProps("productName")}
          />
          {formik.touched.productName && formik.errors.productName && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.productName}</div>
          )}
        </div>

        {/* Detail */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Detail</label>
          <textarea className="w-full p-3 border rounded-lg text-gray-700 focus:ring-2 focus:ring-blue-400 focus:outline-none" {...formik.getFieldProps("detail")} />
          {formik.touched.detail && formik.errors.detail && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.detail}</div>
          )}
        </div>

        {/* Price */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Price</label>
          <div className="flex items-center border rounded-lg w-full md:w-1/4 p-3 bg-gray-50">
            <span className="mr-2 text-gray-600">Rp.</span>
            <input
              type="text"
              className="w-full text-gray-700 bg-transparent outline-none"
              value={formatNumber(formik.values.price)}
              onChange={(e) => {
                const cleanedValue = parseNumber(e.target.value);
                formik.setFieldValue("price", Number(cleanedValue));
                formik.setTouched({ ...formik.touched, price: true });
              }}
            />
          </div>
          {formik.touched.price && formik.errors.price && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.price}</div>
          )}
        </div>

        {/* Weight */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Weight</label>
          <div className="flex items-center border rounded-lg w-1/2 md:w-1/4 p-3 bg-gray-50">
          <input
            type="text"
            className="w-full text-gray-700 bg-transparent outline-none"
            value={formatNumber(formik.values.weight)}
            onChange={(e) => {
              const cleanedValue = parseNumber(e.target.value);
              formik.setFieldValue("weight", Number(cleanedValue));
              formik.setTouched({ ...formik.touched, weight: true });
            }}
          />
            <span className="ml-2 text-gray-600">grams</span>
          </div>
          {formik.touched.weight && formik.errors.weight && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.weight}</div>
          )}
        </div>

        {/* Category */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Category</label>

          {isLoading ? (
            <div className="p-2 border rounded bg-gray-200 animate-pulse h-10 w-full"></div>
          ) : (
            <Select
              options={categoryData?.content?.map((cat: Category) => ({
                value: cat.categoryId,
                label: cat.categoryName,
              })) || []}
              value={
                categoryData?.content
                  ?.map((cat: { categoryId: any; categoryName: any; }) => ({ value: cat.categoryId, label: cat.categoryName }))
                  ?.find((option: { value: number; }) => option.value === Number(formik.values.productCategory)) || null
              }
              onChange={(selectedOption) => {
                formik.setFieldValue("productCategory", selectedOption?.value || "");
                formik.setTouched({ ...formik.touched, productCategory: true });
              }}
              isSearchable
              isDisabled={!categoryData?.content}
              className="text-gray-700 w-full md:w-3/4"
            />
          )}

          {formik.touched.productCategory && formik.errors.productCategory && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.productCategory}</div>
          )}
        </div>

        {/* Product Pictures */}
        <div>
          <label className="block text-gray-700 font-semibold">Product Pictures</label>
          <div className="flex flex-col md:flex-row gap-4">
            {localProductPictures.map((pic, position) => (
              <div key={position} className="relative w-56 h-40 border rounded flex items-center justify-center bg-gray-100">
                {pic ? (
                  <>
                    <img
                      src={pic}
                      alt={`Product ${position + 1}`}
                      className="w-full h-full object-cover rounded"
                    />
                    <button
                      type="button"
                      className={`absolute top-1 right-1 p-1 text-white rounded-full transition ${
                        isSubmitting ? "bg-red-400 cursor-not-allowed" : "bg-red-600 hover:bg-red-700"
                      }`}
                      onClick={() => handleDeletePicture(position + 1)}
                      disabled={isSubmitting}
                    >
                      <FiTrash className="w-5 h-5" />
                    </button>
                  </>
                ) : (
                  <button
                    type="button"
                    className={`absolute top-1 right-1 p-1 text-gray-700 rounded-full transition ${
                      isSubmitting ? "bg-gray-300 cursor-not-allowed" : "bg-gray-300 hover:bg-gray-400"
                    }`}
                    onClick={() => handleUploadPicture(position + 1)}
                    disabled={isSubmitting}
                  >
                    <FiUploadCloud className="w-6 h-6" />
                  </button>
                )}
              </div>
            ))}
          </div>
          {formik.errors.productPictures && typeof formik.errors.productPictures === "string" && (
            <div className="text-red-500 text-sm mt-1">{formik.errors.productPictures}</div>
          )}
        </div>
        <DraftForm
              isSubmitting={isSubmitting}
              handleCancel={handleCancel}
              handleSaveDraft={handleSaveDraft}
              handleDeleteProduct={handleDeleteProduct}
              showCancelModal={showCancelModal}
              setShowCancelModal={setShowCancelModal}
        />
      </form>
      </>
      )}
    </div>
  );
};

export default ProductDraftForm;